    <style>
        :root{--ink:#18213d;--green:#159b62;--pale:#f5f7fb;--line:#e3e9f2;--muted:#75829a;--soft-green:#e8fbf1}*{box-sizing:border-box}body{margin:0;background:var(--pale);font:14px system-ui;color:#26314a}.app{display:grid;grid-template-columns:240px 1fr;min-height:100vh}.side{padding:24px 14px;background:#fff;border-right:1px solid var(--line)}.brand{font-size:18px;font-weight:800;padding:5px 12px 26px;color:var(--ink)}.nav{display:block;width:100%;background:transparent;border:0;padding:11px 12px;border-radius:8px;text-align:left;color:#63708a;font-weight:650;cursor:pointer}.nav:hover,.nav.active{background:var(--soft-green);color:#13794d}.label{margin:20px 12px 7px;font-size:10px;font-weight:800;color:#9da7b9;letter-spacing:.08em}.main{max-width:1450px;width:100%;margin:auto;padding:0 30px 32px}.top{height:82px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}h1,h2,h3{color:var(--ink)}h1{font-size:21px;margin:4px 0}.eyebrow{font-size:10px;letter-spacing:.1em;font-weight:800;color:var(--green)}.user{display:flex;gap:10px;align-items:center}.avatar{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:#e7f8ef;color:#13794d;font-weight:800;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.logout{color:#69758c;text-decoration:none;font-weight:700}.panel{display:none;padding-top:25px}.panel.active{display:block}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;box-shadow:0 4px 16px #1d2a4708}.stat span{color:var(--muted);display:block}.stat strong{font-size:28px;color:var(--ink)}.columns{display:grid;grid-template-columns:1fr 1fr;gap:18px}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:12px;text-align:left;border-bottom:1px solid var(--line)}.table th{font-size:11px;color:var(--muted)}.table tfoot td{background:#f1fbf5;border-top:2px solid #b9e9d1;font-size:15px}.table-wrap{overflow-x:auto}input,select,textarea{width:100%;border:1px solid #d9e1ed;border-radius:8px;padding:10px;font:inherit;background:#fff}.button{border:0;border-radius:8px;background:var(--green);color:#fff;padding:10px 13px;font-weight:750;cursor:pointer}.button.secondary{background:#fff;color:#13794d;border:1px solid #9fd8b9}.button.danger{background:#fff;color:#c24141;border:1px solid #f2caca;padding:9px 10px}.muted{color:var(--muted)}.field-label{display:block;color:var(--ink);font-weight:700;margin:14px 0 6px}.offer-row{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(125px,.78fr) minmax(120px,.72fr) auto;gap:8px;margin-bottom:8px;align-items:center}.add-row{margin:4px 0 8px}.form-total{display:flex;align-items:center;justify-content:space-between;background:#f1fbf5;border:1px solid #c3ebd5;border-radius:8px;padding:12px;margin:14px 0;color:#11653e}.form-total strong{font-size:18px}.report-box{margin-bottom:16px;padding:14px;display:flex;align-items:end;gap:10px;flex-wrap:wrap;background:#f8fafc;border:1px solid var(--line);border-radius:9px}.report-box label{font-size:12px;font-weight:700;color:var(--muted);display:grid;gap:5px}.report-box input{width:170px;padding:8px}.report-box .button{padding:9px 12px;text-decoration:none}.notice{margin-top:18px;color:#13794d}.error{margin:10px 0;padding:10px;border-radius:8px;background:#fff1f1;color:#b42318}@media(max-width:700px){.app{grid-template-columns:1fr}.side{display:flex;gap:4px;overflow:auto;padding:12px}.brand,.label{display:none}.nav{white-space:nowrap;width:auto}.main{padding:0 14px 25px}.stats,.columns{grid-template-columns:1fr}.logout{display:none}.offer-row{grid-template-columns:1fr 1fr}.offer-row .remove-item,.offer-row .remove-expense{grid-column:span 2}.report-box{align-items:stretch}.report-box label{width:100%}.report-box input{width:100%}}
    </style>
</head>
