        <section id="expenses" class="panel"><h2>Matumizi ya Kanisa</h2><div class="columns"><div class="card"><h3>Rekodi matumizi</h3><p class="muted">Ongeza aina nyingi za matumizi na kiasi chake. Jumla itakatwa kwenye salio la wiki na mwezi wa tarehe uliyochagua.</p><form method="post" action="{{ route('church-office.expenses.store') }}">@csrf<label class="field-label">Tarehe ya matumizi</label><input type="date" name="expense_date" value="{{ old('expense_date', now()->format('Y-m-d')) }}" required><label class="field-label">Aina za matumizi na kiasi</label><div id="expense-items">@forelse(old('expense_items', [['expense_type' => '', 'amount' => '']]) as $index => $item)<div class="offer-row"><input name="expense_items[{{ $index }}][expense_type]" value="{{ $item['expense_type'] ?? '' }}" placeholder="Mfano: Umeme, maji, usafiri" required><input class="expense-amount" type="number" min="0.01" step=".01" name="expense_items[{{ $index }}][amount]" value="{{ $item['amount'] ?? '' }}" placeholder="Kiasi (TZS)" required><button type="button" class="button danger remove-expense">Ondoa</button></div>@empty @endforelse</div><button type="button" id="add-expense" class="button secondary add-row">+ Ongeza aina ya matumizi</button><label class="field-label">Maelezo (si lazima)</label><textarea name="notes" placeholder="Maelezo ya matumizi kwa mistari hii">{{ old('notes') }}</textarea><div class="form-total"><span>Jumla ya matumizi itakayohifadhiwa</span><strong id="expense-total">TZS 0.00</strong></div><button class="button">Hifadhi matumizi yote</button></form></div><div class="card"><h3>Matumizi yaliyorekodiwa</h3><div class="table-wrap"><table class="table"><thead><tr><th>Aina</th><th>Kiasi</th><th>Tarehe</th></tr></thead><tbody>@forelse($expenses as $expense)<tr><td>{{ $expense->expense_type }}@if($expense->notes)<br><small class="muted">{{ $expense->notes }}</small>@endif</td><td><strong>TZS {{ number_format($expense->amount,2) }}</strong></td><td>{{ $expense->expense_date->format('d/m/Y') }}</td></tr>@empty<tr><td colspan="3" class="muted">Hakuna matumizi yaliyorekodiwa.</td></tr>@endforelse</tbody><tfoot><tr><td>Jumla ya matumizi yaliyoonyeshwa</td><td colspan="2"><strong>TZS {{ number_format($expenses->sum('amount'), 2) }}</strong></td></tr></tfoot></table></div></div></div></section>
