<template id="offering-row-template"><div class="offer-row"><input placeholder="Aina ya sadaka" required><select required><option value="internal">Ndani ya kanisa</option><option value="external">Nje ya kanisa</option></select><input class="amount-input" type="number" min="0" step=".01" placeholder="Kiasi (TZS)" required><button type="button" class="button danger remove-item">Ondoa</button></div></template>
<template id="expense-row-template"><div class="offer-row"><input placeholder="Mfano: Umeme, maji, usafiri" required><input class="expense-amount" type="number" min="0.01" step=".01" placeholder="Kiasi (TZS)" required><button type="button" class="button danger remove-expense">Ondoa</button></div></template>
<script>
    function show(id,button){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.nav').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');button.classList.add('active')}
    const itemBox=document.getElementById('offering-items'), template=document.getElementById('offering-row-template');
    function refreshRows(){[...itemBox.querySelectorAll('.offer-row')].forEach((row,index)=>{const [type,amount]=row.querySelectorAll('input'),scope=row.querySelector('select');type.name=`items[${index}][offering_type]`;scope.name=`items[${index}][fund_scope]`;amount.name=`items[${index}][amount]`});updateTotal()}
    function updateTotal(){const total=[...document.querySelectorAll('.amount-input')].reduce((sum,input)=>sum+(parseFloat(input.value)||0),0);document.getElementById('form-total').textContent='TZS '+total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}
    document.getElementById('add-offering').addEventListener('click',()=>{itemBox.append(template.content.cloneNode(true));refreshRows();itemBox.lastElementChild.querySelector('input').focus()});
    itemBox.addEventListener('click',event=>{if(event.target.classList.contains('remove-item')&&itemBox.children.length>1){event.target.closest('.offer-row').remove();refreshRows()}});
    itemBox.addEventListener('input',updateTotal);refreshRows();
    const expenseBox=document.getElementById('expense-items'), expenseTemplate=document.getElementById('expense-row-template');
    function refreshExpenseRows(){[...expenseBox.querySelectorAll('.offer-row')].forEach((row,index)=>{const [type,amount]=row.querySelectorAll('input');type.name=`expense_items[${index}][expense_type]`;amount.name=`expense_items[${index}][amount]`});updateExpenseTotal()}
    function updateExpenseTotal(){const total=[...document.querySelectorAll('.expense-amount')].reduce((sum,input)=>sum+(parseFloat(input.value)||0),0);document.getElementById('expense-total').textContent='TZS '+total.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}
    document.getElementById('add-expense').addEventListener('click',()=>{expenseBox.append(expenseTemplate.content.cloneNode(true));refreshExpenseRows();expenseBox.lastElementChild.querySelector('input').focus()});
    expenseBox.addEventListener('click',event=>{if(event.target.classList.contains('remove-expense')&&expenseBox.children.length>1){event.target.closest('.offer-row').remove();refreshExpenseRows()}});
    expenseBox.addEventListener('input',updateExpenseTotal);refreshExpenseRows();
    document.querySelectorAll('.report-link').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const date=document.getElementById('report-date').value;window.open(`{{ route('church-office.offerings.report.pdf') }}?period=${link.dataset.period}&date=${encodeURIComponent(date)}`,'_blank')}));
</script>
</body>
</html>
